1	import type { AgentTool } from "@earendil-works/pi-agent-core";
2	import type { KeatingAgentRuntimeConfig } from "./agent-runtime";
3	
4	export type KeatingCapabilityId = "learner-details" | "media" | "workspace" | "improvement" | "voice";
5	export type CapabilityAvailability = "available" | "unavailable" | "approval-required";
6	
7	export interface CapabilityBundle {
8		id: KeatingCapabilityId;
9		title: string;
10		description: string;
11		availability: CapabilityAvailability;
12		reason?: string;
13		tools: string[];
14	}
15	
16	export interface CapabilityEnvironment {
17		runtime?: KeatingAgentRuntimeConfig;
18		speechEnabled?: boolean;
19	}
20	
21	export interface CapabilityActivationResult {
22		activated: KeatingCapabilityId[];
23		alreadyActive: KeatingCapabilityId[];
24		unavailable: Array<{ id: KeatingCapabilityId; reason: string }>;
25		unknown: string[];
26	}
27	
28	/**
29	 * Transitional baseline while the OpenUI renderer replaces legacy teaching
30	 * cards. These remain available so capability loading can ship independently
31	 * without breaking current conversations.
32	 *
33	 * Lesson plans, concept maps, and verification checklists are no longer
34	 * teaching tools: stream them as OpenUI components (`StudyPlan`,
35	 * `ConceptMap`, `SharedNotes`, `Explanation`) inside `LearningSurface` so
36	 * the model can iterate without bouncing through a one-shot tool call.
37	 */
38	export const BASELINE_TEACHING_TOOLS = new Set([
39		"quiz",
40		"deck",
41		"feedback",
42		"grade_quiz",
43		"grade_question_checks",
44		"remember_learner_profile",
45		"set_learner_goal",
46		"update_goal_step",
47	]);
48	
49	const TOOL_NAMES: Record<KeatingCapabilityId, string[]> = {
50		"learner-details": ["inspect_learning_context"],
51		media: ["animate", "generate_image"],
52		workspace: ["workspace_inspect", "workspace_change", "workspace_exec"],
53		improvement: ["evaluate_teaching", "request_teaching_improvement"],
54		voice: ["keating_voice"],
55	};
56	
57	function availableWorkspaceTools(environment: CapabilityEnvironment): string[] {
58		const runtime = environment.runtime;
59		if (!runtime) return [];
60		const tools = new Set<string>();
61		const nodePod = runtime.mode === "browser-nodepod";
62		const remote = runtime.capabilities.remoteSandbox;
63		const canInspect = nodePod || remote || !!runtime.projectFilesEndpoint;
64		const canExecute = nodePod || runtime.capabilities.remoteSandbox || !!runtime.localExecEndpoint;
65		const canChange = nodePod || remote || (!!runtime.projectFilesEndpoint && !!runtime.localExecEndpoint);
66		if (canInspect) tools.add("workspace_inspect");
67		if (canExecute) tools.add("workspace_exec");
68		if (canChange) tools.add("workspace_change");
69		return [...tools];
70	}
71	
72	export function buildCapabilityCatalog(environment: CapabilityEnvironment = {}): CapabilityBundle[] {
73		const workspaceTools = availableWorkspaceTools(environment);
74		return [
75			{
76				id: "learner-details",
77				title: "Learner details",
78				description: "Inspect deeper learner history, goals, review timing, or progress when the automatically loaded summary is insufficient.",
79				availability: "available",
80				tools: [...TOOL_NAMES["learner-details"]],
81			},
82			{
83				id: "media",
84				title: "Media",
85				description: "Generate images and render authored Hyperframes animations.",
86				availability: "available",
87				tools: [...TOOL_NAMES.media],
88			},
89			{
90				id: "workspace",
91				title: "Workspace",
92				description: "Inspect, edit, validate, and execute within an attached project or sandbox.",
93				availability: workspaceTools.length ? "available" : "unavailable",
94				reason: workspaceTools.length ? undefined : "No NodePod, remote sandbox, host-project, or local execution backend is connected.",
95				tools: workspaceTools,
96			},
97			{
98				id: "improvement",
99				title: "Teaching improvement",
100				description: "Evaluate teaching evidence and evolve policy or prompts outside the active teaching moment.",
101				availability: "available",
102				tools: [...TOOL_NAMES.improvement],
103			},
104			{
105				id: "voice",
106				title: "Voice",
107				description: "Produce speech through the configured voice runtime.",
108				availability: environment.speechEnabled ? "available" : "unavailable",
109				reason: environment.speechEnabled ? undefined : "Voice is disabled in this session.",
110				tools: [...TOOL_NAMES.voice],
111			},
112		];
113	}
