115	export function capabilityCatalogPrompt(catalog: CapabilityBundle[]): string {
116		const rows = catalog.map((bundle) => {
117			const suffix = bundle.availability === "available"
118				? "available"
119				: `${bundle.availability}: ${bundle.reason ?? "not configured"}`;
120			return `- ${bundle.id}: ${bundle.description} (${suffix})`;
121		});
122		return [
123			"### Optional capability bundles",
124			"Normal teaching uses the baseline interaction capabilities. Optional tool schemas are loaded only when needed. Call `activate_capabilities` with one or more available bundle ids before using them.",
125			...rows,
126		].join("\n");
127	}
128	
129	function activationTool(controller: KeatingCapabilityController): AgentTool {
130		return {
131			name: "activate_capabilities",
132			label: "activate_capabilities",
133			description: "Load one or more optional capability bundles for subsequent work. Activate all bundles you expect to need in one call.",
134			executionMode: "sequential",
135			parameters: {
136				type: "object",
137				properties: {
138					ids: {
139						type: "array",
140						items: { type: "string", enum: ["learner-details", "media", "workspace", "improvement", "voice"] },
141						minItems: 1,
142						uniqueItems: true,
143						description: "Capability bundle ids to load.",
144					},
145				},
146				required: ["ids"],
147				additionalProperties: false,
148			},
149			execute: async (_toolCallId: string, params: unknown) => {
150				const ids = Array.isArray((params as { ids?: unknown })?.ids)
151					? (params as { ids: unknown[] }).ids.filter((id): id is string => typeof id === "string")
152					: [];
153				const result = controller.activate(ids);
154				const lines = ["# Capability activation"];
155				if (result.activated.length) lines.push(`- activated: ${result.activated.join(", ")}`);
156				if (result.alreadyActive.length) lines.push(`- already active: ${result.alreadyActive.join(", ")}`);
157				for (const item of result.unavailable) lines.push(`- unavailable ${item.id}: ${item.reason}`);
158				if (result.unknown.length) lines.push(`- unknown: ${result.unknown.join(", ")}`);
159				if (result.activated.length) lines.push("- status: activated tools will be available in the automatic continuation");
160				controller.notifyActivation(result);
161				return {
162					content: [{ type: "text", text: lines.join("\n") }],
163					details: { tool: "activate_capabilities", ...result },
164					terminate: result.activated.length > 0,
165				};
166			},
167		} as AgentTool;
168	}
