170	export class KeatingCapabilityController {
171		private environment: CapabilityEnvironment;
172		private allTools: AgentTool[] = [];
173		private readonly active = new Set<KeatingCapabilityId>();
174		private listener?: (tools: AgentTool[]) => void;
175		private activationListener?: (result: CapabilityActivationResult) => void;
176		private readonly activationTool: AgentTool;
177	
178		constructor(environment: CapabilityEnvironment = {}) {
179			this.environment = environment;
180			this.activationTool = activationTool(this);
181		}
182	
183		setListener(listener: (tools: AgentTool[]) => void): void {
184			this.listener = listener;
185		}
186	
187		setActivationListener(listener: (result: CapabilityActivationResult) => void): void {
188			this.activationListener = listener;
189		}
190	
191		setEnvironment(environment: CapabilityEnvironment): void {
192			this.environment = environment;
193			this.dropUnavailableCapabilities();
194			this.notify();
195		}
196	
197		setAllTools(tools: AgentTool[]): AgentTool[] {
198			this.allTools = [...tools];
199			const selected = this.tools();
200			this.listener?.(selected);
201			return selected;
202		}
203	
204		catalog(): CapabilityBundle[] {
205			const registered = new Set(this.allTools.map((tool) => tool.name));
206			return buildCapabilityCatalog(this.environment).map((bundle) => {
207				if (bundle.availability !== "available") return bundle;
208				const missing = bundle.tools.filter((name) => !registered.has(name));
209				if (missing.length === 0) return bundle;
210				return {
211					...bundle,
212					availability: "unavailable",
213					reason: `Tool schemas are not registered: ${missing.join(", ")}.`,
214				};
215			});
216		}
217	
218		activeIds(): KeatingCapabilityId[] {
219			return [...this.active];
220		}
221	
222		activate(ids: string[]): CapabilityActivationResult {
223			const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
224			const result: CapabilityActivationResult = { activated: [], alreadyActive: [], unavailable: [], unknown: [] };
225			for (const rawId of ids) {
226				const bundle = catalog.get(rawId as KeatingCapabilityId);
227				if (!bundle) {
228					result.unknown.push(rawId);
229					continue;
230				}
231				if (bundle.availability !== "available") {
232					result.unavailable.push({ id: bundle.id, reason: bundle.reason ?? "Capability is not available." });
233					continue;
234				}
235				if (this.active.has(bundle.id)) result.alreadyActive.push(bundle.id);
236				else {
237					this.active.add(bundle.id);
238					result.activated.push(bundle.id);
239				}
240			}
241			if (result.activated.length) this.notify();
242			return result;
243		}
244	
245		tools(): AgentTool[] {
246			const activeToolNames = new Set(BASELINE_TEACHING_TOOLS);
247			for (const bundle of this.catalog()) {
248				if (this.active.has(bundle.id) && bundle.availability === "available") {
249					for (const name of bundle.tools) activeToolNames.add(name);
250				}
251			}
252			return [this.activationTool, ...this.allTools.filter((tool) => activeToolNames.has(tool.name))];
253		}
254	
255		private dropUnavailableCapabilities(): void {
256			const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
257			for (const id of this.active) {
258				if (catalog.get(id)?.availability !== "available") this.active.delete(id);
259			}
260		}
261	
262		private notify(): void {
263			this.listener?.(this.tools());
264		}
265	
266		notifyActivation(result: CapabilityActivationResult): void {
267			this.activationListener?.(result);
268		}
269	}
