16	export function createTeachingTools(storage: KeatingStorage): AgentTool[] {
17		return [
18			createTool(
19				"deck",
20				"Build a spaced-repetition flashcard deck that the chat renders inline. You must author the cards yourself from the material the learner actually covered. Pass `cards` as an array of {front, back, tags?}; generic or duplicate cards are rejected. Keating persists the deck and initializes real SM-2 review state for each card.",
21				{
22					topic: { type: "string", description: "The topic this deck covers" },
23					title: { type: "string", description: "Optional deck title shown in the inline review card. Defaults to '<topic> flashcards'." },
24					description: { type: "string", description: "Optional one-line note about what the learner should practice with this deck." },
25					cards: {
26						type: "array",
27						description: "REQUIRED. Model-authored flashcards: [{ front, back, tags? }]. Write concrete retrieval prompts and answers from the lesson; no placeholders or generic cards.",
28						items: {
29							type: "object",
30							properties: {
31								front: { type: "string", description: "Prompt side of the card." },
32								back: { type: "string", description: "Answer side of the card." },
33								tags: { type: "array", items: { type: "string" }, description: "Optional topic tags for the card." },
34							},
35						},
36					},
37				},
38				async (params) => {
39					const topic = String(params.topic ?? "").trim();
40					if (!topic) return "Topic required.";
41	
42					const validated = validateDeckDraft(params.cards);
43					if (!validated.ok) {
44						return `Author the flashcards yourself. ${validated.error} No template fallback exists.`;
45					}
46	
47					const resolved = resolveTopic(topic);
48					const title = String(params.title ?? "").trim() || `${resolved.title} flashcards`;
49					const description = String(params.description ?? "").trim() || undefined;
50					const baseSlug = slugifyDeckTitle(title) || `${resolved.slug}-flashcards`;
51					const existing = await storage.getDeckBySlug(baseSlug);
52					const now = Date.now();
53					const cards = (validated.cards ?? []).map((card, index) => ({
54						id: existing?.cards[index]?.id ?? draftDeckCardId(baseSlug, index),
55						front: card.front,
56						back: card.back,
57						...(card.tags ? { tags: card.tags } : {}),
58						srs: existing?.cards[index]?.srs ?? initialSrsState(now),
59						createdAt: existing?.cards[index]?.createdAt ?? now,
60						updatedAt: now,
61					}));
62	
63					const saved = await storage.saveDeck({
64						id: existing?.id,
65						createdAt: existing?.createdAt,
66						topic: resolved.title,
67						slug: baseSlug,
68						title,
69						description,
70						cards,
71					});
72	
73					return [
74						`Created deck **${saved.title}** with ${saved.cards.length} cards.`,
75						"",
76						`<keating-deck json=${JSON.stringify(JSON.stringify(saved))} />`,
77					].join("\n");
78				}
79			),
80	
81			// bench - Run learner-feedback benchmark
82			createTool(
83				"outputs",
84				"Browse all saved Keating artifacts (plans, maps, benchmarks, evolutions, etc).",
85				{},
86				async () => {
87					const artifacts = await storage.listArtifacts();
88	
89					if (artifacts.length === 0) {
90						return "No artifacts yet.";
91					}
92	
93					const list = artifacts
94						.slice(0, 20)
95						.map((a) => `- ${a.label} (${new Date(a.createdAt).toLocaleDateString()})`)
96						.join("\n");
97	
98					return `Keating Artifacts (${artifacts.length} total)\n\n${list}`;
99				}
100			),
101	
102			// learner_state - Load learner profile (agent-facing, renamed from /state)
103			createTool(
104				"learner_state",
105				"Legacy on-demand learner profile inspection. A compact learner summary is loaded automatically before the first model turn, so do not call this at session start. Prefer inspect_learning_context when deeper details are genuinely needed.",
106				{},
107				async () => {
108					const state = await storage.getLearnerState();
109	
110					const upCount = state.feedbackHistory.filter((f) => f.signal === "thumbs-up").length;
111					const downCount = state.feedbackHistory.filter((f) => f.signal === "thumbs-down").length;
112					const confusedCount = state.feedbackHistory.filter((f) => f.signal === "confused").length;
113	
114					const topicList = state.topicsExplored.slice(-10).map((t) => `- ${t}`).join("\n") || "None yet";
115					const profileBeliefs = (state.profileBeliefs ?? []).slice(-10).map((belief) =>
116						`- ${belief.category}: ${belief.value} (${belief.source}, ${Math.round(belief.confidence * 100)}%)`
117					).join("\n") || "- None recorded yet";
118	
119					return `Learner Profile:
120	- Sessions: ${state.sessionsCount || 0}
121	- Topics explored: ${state.topicsExplored.length}
122	${topicList}
123	- Feedback: 👍${upCount} 👎${downCount} 🤔${confusedCount}
124	- Motivations and preferences:
125	${profileBeliefs}
126	- Last session: ${state.lastSessionAt ? new Date(state.lastSessionAt).toLocaleString() : "First session"}`;
127				}
128			),
129	
130			// auto_improve - Full autonomous self-improvement loop
131			createTool(
132				"timeline",
133				"Legacy on-demand engagement timeline. Review priorities are loaded automatically before the first model turn; prefer inspect_learning_context when the full timeline is needed.",
134				{},
135				async () => {
136					const state = await storage.getLearnerState();
137					const coveredTopics: CoveredTopic[] = (state.topicsExplored || []).map((slug) => {
138						const topicFeedback = state.feedbackHistory.filter((f) => f.topic === slug);
139						const lastEntry = topicFeedback[topicFeedback.length - 1];
140						const upCount = topicFeedback.filter((f) => f.signal === "thumbs-up").length;
141						const totalCount = topicFeedback.length || 1;
142						const resolved = resolveTopic(slug);
143						return {
144							slug: resolved.slug,
145							domain: resolved.domain,
146							lastSeenAt: lastEntry?.createdAt ?? (state.lastSessionAt ?? Date.now()),
147							masteryEstimate: Math.min(1, 0.3 + (upCount / totalCount) * 0.5),
148							sessionCount: totalCount,
149						};
150					});
151	
152					if (coveredTopics.length === 0) {
153						return "No topics covered yet.";
154					}
155	
156					const timeline = buildEngagementTimeline(coveredTopics, DEFAULT_ENGAGEMENT_POLICY);
157					return engagementTimelineToMarkdown(timeline);
158				}
159			),
160	
161			// due - Show topics due for review
162			createTool(
163				"due",
164				"Legacy on-demand due-review inspection. A compact due-review summary is loaded automatically before the first model turn; prefer inspect_learning_context for deeper review details.",
165				{},
166				async () => {
167					const state = await storage.getLearnerState();
168					const coveredTopics: CoveredTopic[] = (state.topicsExplored || []).map((slug) => {
169						const topicFeedback = state.feedbackHistory.filter((f) => f.topic === slug);
170						const lastEntry = topicFeedback[topicFeedback.length - 1];
171						const upCount = topicFeedback.filter((f) => f.signal === "thumbs-up").length;
172						const totalCount = topicFeedback.length || 1;
173						const resolved = resolveTopic(slug);
174						return {
175							slug: resolved.slug,
176							domain: resolved.domain,
177							lastSeenAt: lastEntry?.createdAt ?? (state.lastSessionAt ?? Date.now()),
178							masteryEstimate: Math.min(1, 0.3 + (upCount / totalCount) * 0.5),
179							sessionCount: totalCount,
180						};
181					});
182	
183					if (coveredTopics.length === 0) {
184						return "No topics covered yet.";
185					}
186	
187					const due = getDueTopics(coveredTopics, DEFAULT_ENGAGEMENT_POLICY);
188					if (due.length === 0) {
189						return "All topics are up to date. No reviews needed.";
190					}
191	
192					return dueTopicsToMarkdown(due);
193				}
194			),
195	
196			// ask_user_question - Ask the learner one or more questions as an interactive form
197			createTool(
198				"remember_learner_profile",
199				"Preserve a useful, non-sensitive fact about how this learner wants to learn or communicate. Use this proactively when the learner states a preference, motivation, or interest, or when repeated behavior provides concrete evidence. Explicit statements are certain; observations must remain tentative. Never infer protected, medical, psychological, or identity traits.",
200				{
201					category: {
202						type: "string",
203						enum: ["motivation", "communication-preference", "learning-preference", "interest"],
204						description: "The kind of learner-specific fact being remembered.",
205					},
206					value: { type: "string", description: "A short, actionable description, such as 'prefers concise answers followed by examples'." },
207					source: { type: "string", enum: ["explicit", "observed"], description: "Use explicit only when the learner actually said it; otherwise observed." },
208					evidence: { type: "string", description: "The learner statement or repeated interaction pattern supporting this belief." },
209					confidence: { type: "number", minimum: 0, maximum: 1, description: "Optional confidence for observed evidence. Observations are capped at 0.65." },
210				},
211				async (params) => {
212					const category = String(params.category ?? "") as import("../storage").LearnerProfileCategory;
213					const allowed = new Set(["motivation", "communication-preference", "learning-preference", "interest"]);
214					if (!allowed.has(category)) return "Choose a valid learner profile category.";
215					const source = params.source === "explicit" ? "explicit" : "observed";
216					const belief = await storage.rememberLearnerProfileBelief({
217						category,
218						value: String(params.value ?? ""),
219						source,
220						evidence: String(params.evidence ?? ""),
221						confidence: typeof params.confidence === "number" ? params.confidence : undefined,
222					});
223					return `Remembered ${belief.category}: ${belief.value} (${belief.source}, ${Math.round(belief.confidence * 100)}% confidence).`;
224				},
225				["category", "value", "source", "evidence"],
226			),
227	
228			createTool(
229				"set_learner_goal",
230				"Capture what the learner wants to ACCOMPLISH (a task or project) and build a long-horizon, multi-step curriculum that scaffolds toward it. The goal is persisted and its progress is tracked across sessions. Design the `steps` yourself as an ordered path (concept → practice → project → reflection); if you omit steps, a scaffold is generated from the anchor topic. Use update_goal_step to advance it later.",
231				{
232					title: { type: "string", description: "The goal/task the learner wants to accomplish (e.g. 'Build a personal-finance tracker app')" },
233					description: { type: "string", description: "What success looks like / scope of the goal" },
234					motivation: { type: "string", description: "Why the learner wants this — used to keep them oriented" },
235					target_date: { type: "string", description: "Optional target date or timeframe (free text)" },
236					topic: { type: "string", description: "Anchor topic used to auto-scaffold steps when `steps` is omitted" },
237					steps: {
238						type: "array",
239						description: "Ordered curriculum steps building toward the goal",
240						items: {
241							type: "object",
242							properties: {
243								title: { type: "string", description: "Step title" },
244								description: { type: "string", description: "What the learner does in this step" },
245								kind: { type: "string", description: "One of: concept, practice, project, milestone, reflection" },
246								topic: { type: "string", description: "Topic this step centers on (enables plan/quiz tooling)" },
247								success_criteria: { type: "array", items: { type: "string" }, description: "How the learner knows this step is done" },
248							},
249						},
250					},
251				},
252				async (params) => {
253					const title = String(params.title ?? "").trim();
254					if (!title) return "Error: a goal title is required.";
255	
256					const rawSteps = Array.isArray(params.steps) ? params.steps : [];
257					const steps: GoalStepInput[] = rawSteps
258						.filter((s): s is Record<string, unknown> => !!s && typeof s === "object")
259						.map((s) => ({
260							title: String(s.title ?? ""),
261							description: s.description ? String(s.description) : undefined,
262							kind: s.kind ? (String(s.kind) as GoalStepInput["kind"]) : undefined,
263							topic: s.topic ? String(s.topic) : undefined,
264							successCriteria: Array.isArray(s.success_criteria)
265								? (s.success_criteria as unknown[]).filter((c): c is string => typeof c === "string")
266								: undefined,
267						}));
268	
269					const goal = buildGoal({
270						title,
271						description: params.description ? String(params.description) : undefined,
272						motivation: params.motivation ? String(params.motivation) : undefined,
273						targetDate: params.target_date ? String(params.target_date) : undefined,
274						topic: params.topic ? String(params.topic) : undefined,
275						steps: steps.length > 0 ? steps : undefined,
276					});
277	
278					const saved = await storage.saveGoal(goal);
279					const progress = computeGoalProgress(saved);
280					const summary = [
